Translate("zhCN", "deadwind-pass", {
	title = "逆风小径",
	aliases = { "逆风" },
	sections = {
		{
			title = "概述",
			text = [=[逆风小径是{link:duskwood}暮色森林{/link}与{link:swamp-of-sorrows}悲伤沼泽{/link}之间群山中一道荒芜的裂谷。一股寒风不停地在其中呜咽，小径也因此得名。这里几乎没有什么能好好生长。树木灰暗无叶，草稀疏而失色，头顶的天空似乎永远是灰烬的颜色。在小径南部一片支离破碎的深凹地中，矗立着{link:karazhan}卡拉赞{/link}之塔。它曾是最后的守护者{link:medivh}麦迪文{/link}的居所，也是他死去的地方。不得不穿越逆风小径的旅人都沿着大路走，少言寡语，也不会长久地望向那座塔。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载是谁最先为这条小径命名，也没有记载它是否曾经青翠。可以肯定的是，它是因为中心的那座塔才为外界所知的。在{link:first-war}第一次战争{/link}之前的那些年里，{link:medivh}麦迪文{/link}以{link:karazhan}卡拉赞{/link}为家，并在那里谋划了将{red:draenor}德拉诺{/red}的{link:orcs}兽人{/link}带入{link:azeroth}艾泽拉斯{/link}的长远计划。这条小径位于古老的{link:kingdom-of-stormwind}艾泽拉斯{/link}王国的东南边缘，王国的百姓很少有理由去那里。守护者是国王的朋友，他的塔一直无人打扰。]=],
		},
		{
			title = "当今",
			text = [=[{link:medivh}麦迪文{/link}早已死去，他的塔黑暗而紧闭。这条小径如今不属于任何王国。{link:kingdom-of-stormwind}暴风城{/link}不会派巡逻队到这么远的东方，{link:horde}部落{/link}在这里也没有据点。不安的灵魂在{link:karazhan}卡拉赞{/link}脚下的废墟间飘荡，苍白的不死之物在塔后照料着{link:morgan-s-plot}摩根墓场{/link}的坟墓。{link:ogres}食人魔{/link}在南方的路边、在一条名为{link:the-vice}罪恶谷{/link}的狭窄{link:stranglethorn-vale}山谷{/link}中挖建了他们的土丘。巨大的食腐鸟在峡谷上空盘旋。在大路上，前往{link:swamp-of-sorrows}悲伤沼泽{/link}和{link:blasted-lands}诅咒之地{/link}的商人与士兵趁着白天匆匆通过。在{link:duskwood}暮色森林{/link}，{link:darkshire}夜色镇{/link}的人们说，屠杀约根一家的{link:dark-riders}黑暗骑士{/link}就是从这条小径下来的，而没有人知道他们回去后去了哪里。]=],
		},
		{
			title = "居民",
			text = [=[• {b}不安的亡者。{/b}阴影、哀嚎的幽灵和受诅咒的灵魂在{link:karazhan}卡拉赞{/link}前的废屋中出没。他们是谁的灵魂，没有活着的目击者说得出来。
• {b}{link:morgan-s-plot}摩根墓场{/link}的不死者。{/b}苍白的看守者和居民守着塔后的礼拜堂和墓地。
• {b}逆风食人魔。{/b}{link:deadwind-ogres}逆风食人魔{/link}占据着{link:the-vice}罪恶谷{/link}的土丘和{link:grosh-gok-compound}格罗高克营地{/link}，其中有术士和{link:ogres}食人魔{/link}法师。
• {b}食腐鸟。{/b}被称为天空之影的秃鹫在北方的峡谷和小径的空地上空盘旋。
• {b}{link:dark-riders}黑暗骑士{/link}。{/b}白天在这里看不到他们。然而{link:duskwood}暮色森林{/link}的幸存者说，他们正是从逆风小径骑马而来。]=],
		},
		{
			title = "历史",
			text = [=[• {b}守护者之塔。{/b}{link:medivh}麦迪文{/link}从少年时的长眠中醒来后，便在{link:karazhan}卡拉赞{/link}住了下来。他在那里研究学问，收集了一座宏大的图书馆，很少接待客人。
• {b}打开传送门。{/b}麦迪文从塔中跨越虚空，触及德拉诺和术士{link:gul-dan}古尔丹{/link}。他们一起在遥远南方的黑色{link:swamp-of-sorrows}沼泽{/link}中打开了{link:dark-portal}黑暗之门{/link}。
• {b}学徒与使者。{/b}{link:dalaran}达拉然{/link}的{link:kirin-tor}肯瑞托{/link}派年轻的法师{link:khadgar}卡德加{/link}去做麦迪文的学徒。半{link:orcs}兽人{/link}{link:garona}迦罗娜{/link}以{link:horde}部落{/link}使者的身份来到塔中。他们两人一起得知了守护者背叛的真相。
• {b}守护者之死。{/b}{link:anduin-lothar}安度因·洛萨{/link}爵士和卡德加登上卡拉赞，与麦迪文对峙。守护者就在那里被杀。当时正在探入麦迪文心智的古尔丹，陷入了长久的昏迷。
• {b}沉寂。{/b}从那天起，这座塔便一片黑暗。{link:first-war}第一次战争{/link}和{link:second-war}第二次战争{/link}都与它擦肩而过，它周围的小径成了生者避而远之的地方。]=],
		},
		{
			title = "小径传说",
			text = [=[• 从{link:duskwood}暮色森林{/link}通往{link:swamp-of-sorrows}悲伤沼泽{/link}的大路是唯一安全的通道。路旁立着古老的警告牌，其中一块只简单地写着：“回头吧！”
• {link:the-crossroads}十字路口{/link}旁立着一棵枯树，被吊死的人仍在它的枝头摇晃。暮色森林没有人声称知道是谁吊死了他们。
• {link:the-vice}罪恶谷{/link}的{link:ogres}食人魔{/link}让营地里的篝火和大锅一直燃烧着。他们希望在如此死寂的土地上找到什么，没有人去问过他们。
• 塔后有一座小礼拜堂和一片墓地。无论曾在那里聚集的是什么样的会众，他们的死者都不得安息。]=],
		},
		{
			title = "未载",
			text = [=[没有任何编年史讲述这片小径的土地为何如此荒芜，也没有讲述{link:medivh}麦迪文{/link}到来之前它是否就已如此。也没有任何记载说明谁曾住在{link:karazhan}卡拉赞{/link}下方的废屋中，或者他们后来怎样了。本条目记载的是旅人所见，以及守护者的史书所确认的内容。]=],
		},
	},
	mentions = {
		{
			text = [=[{link:sven-yorgen}斯温{/link}的复仇，逆风小径的{link:dark-riders}黑暗骑士{/link}在此首次被提及]=],
		},
	},
})

Translate("zhCN", "karazhan", {
	title = "卡拉赞",
	aliases = { "麦迪文之塔", "卡拉赞之塔" },
	sections = {
		{
			title = "概述",
			text = [=[卡拉赞是最后的守护者{link:medivh}麦迪文{/link}的塔。它从{link:deadwind-pass}逆风小径{/link}南部的一片深凹地中拔地而起，是一座高耸的{link:mirkfallon-lake}暗色{/link}石塔，下方散落着废弃的房屋。多年来，它是世上最强大的法师之一的居所。它也是{link:first-war}第一次战争{/link}的发端之地，以及它的主人死去的地方。如今它的大门紧闭。没有仆人在门口应答，也没有为客人点亮的灯火。]=],
		},
		{
			title = "守护者之家",
			text = [=[{link:medivh}麦迪文{/link}在{link:northshire-abbey}北郡修道院{/link}度过少年时的长眠之后，以成年人的身份来到卡拉赞。他和一小群仆人住在那里，由一位年迈的管家领头。塔中有一座宏大的图书馆，摆满奇异仪器的房间，以及一座向群星敞开的观星台。住在塔里的人发现，它并不总是停留在当下。{link:khadgar}卡德加{/link}在做学徒期间，曾看到塔的厅堂中浮现又消散的景象，它们属于别的日子，有些早已过去，有些尚未到来。{link:kirin-tor}肯瑞托{/link}的法师们一直渴望了解这座塔的秘密。他们中没有一个人曾受邀入内，直到守护者终于同意收一个学徒。]=],
		},
		{
			title = "背叛",
			text = [=[{link:medivh}麦迪文{/link}在这些墙内跨越虚空，触及了垂死的世界{red:draenor}德拉诺{/red}。他找到了术士{link:gul-dan}古尔丹{/link}和为他效力的{link:orcs}兽人{/link}，他们一起打开了{link:dark-portal}黑暗之门{/link}。多年来，守护者在{link:stormwind-city}暴风城{/link}的朋友们对此一无所知。真相是通过两个意想不到的盟友从塔中传出来的：{link:dalaran}达拉然{/link}派来的学徒{link:khadgar}卡德加{/link}，以及{link:horde}部落{/link}的半兽人使者{link:garona}迦罗娜{/link}。他们把在卡拉赞得知的一切带给了国王{link:llane-wrynn}莱恩·乌瑞恩{/link}。]=],
		},
		{
			title = "最后一战",
			text = [=[{link:anduin-lothar}安度因·洛萨{/link}爵士和{link:khadgar}卡德加{/link}回到卡拉赞，要从根源上结束这场战争，{link:garona}迦罗娜{/link}也与他们站在一起。他们在守护者自己的塔中与他交战，{link:medivh}麦迪文{/link}被杀。就在那一刻，{link:gul-dan}古尔丹{/link}正在守护者的心智中搜寻{link:sargeras}萨格拉斯{/link}之墓的秘密。麦迪文死去时，这名术士陷入了昏迷，很久都没有醒来。卡德加走下塔时，已经苍老得远超他的年纪。卡拉赞在他身后被留下，空无一人。]=],
		},
		{
			title = "如今",
			text = [=[塔已被封闭。在它脚下的废屋间飘荡的灵魂，是它仅有的伴侣。然而{link:medivh}麦迪文{/link}的知识并没有完全消失。这座塔最后的学徒{link:khadgar}卡德加{/link}所写的论文，至今仍被{link:stormwind-city}暴风城{/link}的学者抄写和研究，从{link:nethergarde-keep}守望堡{/link}守卫{link:dark-portal}黑暗之门{/link}的{link:the-night-watch}守望者{/link}们也在寻找它们。]=],
		},
		{
			title = "未载",
			text = [=[没有任何编年史讲述是谁建造了卡拉赞，它建于何时，或者它为何矗立在如此荒凉的地方。如今它紧闭的门后有什么，没有活着的目击者写下过。]=],
		},
	},
	chapters = {
		{
			title = "学徒的论文",
			hint = "找回一位学者遗失的论文，把它交给守卫黑暗之门的守望者。",
			text = [=[{link:stormwind-city}暴风城{/link}学院的一名信使带着一份珍贵的文本出发前往{link:nethergarde-keep}守望堡{/link}：{link:khadgar}卡德加{/link}关于诸界汇聚的论文。他在{link:swamp-of-sorrows}悲伤沼泽{/link}把它弄丢了，落入了沼泽的生物之手。当它终于送到要塞时，索要它的那位{link:the-night-watch}守望者{/link}迫不及待地想要开始研读。那个曾在{link:medivh}麦迪文{/link}身边学习的人，比任何在世的人都更清楚两个世界是如何连接在一起的。如今守望着传送门的人们也希望弄懂这一点。]=],
		},
	},
	mentions = {
		{ text = "马岑的请求，学院图书馆的求助" },
		{
			text = [=[马岑的请求，把{link:khadgar}卡德加{/link}的论文送往{link:nethergarde-keep}守望堡{/link}]=],
		},
	},
	bonds = {
		{ id = "medivh", name = "麦迪文", note = "它的主人" },
		{ id = "khadgar", name = "卡德加", note = "它最后的学徒" },
		{ id = "garona", name = "迦罗娜", note = "作为部落的使者来到这里" },
		{ id = "anduin-lothar", name = "安度因·洛萨", note = "在这里杀死了守护者" },
		{ id = "aegwynn", name = "艾格文", note = "守护者的母亲" },
	},
})

Translate("zhCN", "morgan-s-plot", {
	title = "摩根墓场",
	sections = {
		{
			title = "概述",
			text = [=[摩根墓场是一座小礼拜堂和一片墓地，就在{link:karazhan}卡拉赞{/link}的后面。它的墓碑歪斜，屋顶塌了一半。它也许曾为塔脚下的村庄服务，但如今已没有人记得谁葬在那里，也没有人记得它名字中的{link:morgan-stern}摩根{/link}可能是谁。这些坟墓并没有被放过。苍白的身影，即这里的不死看守者和居民，在礼拜堂与山坡之间行走，仿佛他们仍有职责要履行。他们不欢迎访客。]=],
		},
	},
})

Translate("zhCN", "deadman-s-crossing", {
	title = "死者十字",
	sections = {
		{
			title = "概述",
			text = [=[死者十字是穿过{link:deadwind-pass}逆风小径{/link}的大路分岔的地方。一条路向西通往{link:duskwood}暮色森林{/link}，一条向东通往{link:swamp-of-sorrows}悲伤沼泽{/link}，还有一条向南，下到{link:karazhan}卡拉赞{/link}所在的凹地。{link:the-crossroads}十字路口{/link}旁立着一棵枯树，枝头挂着被吊死者的尸体。一块路标给旅人们直截了当的忠告：回头吧。大多数人以自己的方式听从了它：他们待在大路上，不走南边的那条岔路。]=],
		},
	},
})

Translate("zhCN", "ariden-s-camp", {
	title = "埃瑞丁营地",
	sections = {
		{
			title = "概述",
			text = [=[埃瑞丁营地是一处荒废的营地，就在穿过{link:deadwind-pass}逆风小径{/link}的大路以北。只剩下一个冰冷的火坑和几件被丢弃的物品。无论埃瑞丁是谁，他或她匆忙离开了营地，或者根本就没有离开。很少有旅人在这里停留。在一片亡者行走、{link:ogres}食人魔{/link}监视着道路的土地上，一堆孤零零的火是一种很少有人愿意发出的邀请。]=],
		},
		{
			title = "未载",
			text = [=[当今的编年史中没有一部记载埃瑞丁是谁，是什么把他带到{link:deadwind-pass}逆风小径{/link}，或者他后来怎样了。]=],
		},
	},
})

Translate("zhCN", "the-vice", {
	title = "罪恶谷",
	sections = {
		{
			title = "概述",
			text = [=[罪恶谷是{link:deadwind-pass}逆风小径{/link}东南部的一条狭窄{link:stranglethorn-vale}山谷{/link}，陡峭的岩壁在这里向通往{link:karazhan}卡拉赞{/link}的道路合拢。{link:deadwind-ogres}逆风食人魔{/link}在这些岩壁中挖建了他们的土丘。他们从洞穴中监视着下方的道路，他们的篝火和大锅在石头间冒着烟。蛮兵和重殴者守卫着营地，而术士和{link:ogres}食人魔{/link}法师守在火边。没有人知道食人魔为何选择如此死寂的地方安家。]=],
		},
	},
})

Translate("zhCN", "grosh-gok-compound", {
	title = "格罗高克营地",
	aliases = { "格罗高克" },
	sections = {
		{
			title = "概述",
			text = [=[格罗高克营地是{link:the-vice}罪恶谷{/link}中最大、也是最南边的{link:ogres}食人魔{/link}土丘。它的洞穴深入通往{link:karazhan}卡拉赞{/link}的道路上方的悬崖。这里是{link:deadwind-ogres}逆风食人魔{/link}的主要巢穴，氏族的术士们一直待在它附近。在营地附近偏离大路的旅人，很少有机会再偏离第二次。]=],
		},
	},
})

Translate("zhCN", "sleeping-gorge", {
	title = "沉睡峡谷",
	sections = {
		{
			title = "概述",
			text = [=[沉睡峡谷是{link:deadwind-pass}逆风小径{/link}东部的一道小裂谷。向南通往{link:karazhan}卡拉赞{/link}的小路之一沿着它的谷底走上一段，然后向东转入{link:the-vice}罪恶谷{/link}。不管是谁给它起的名字，这道峡谷都不是休憩之地。穿过它的旅人都放轻脚步，因为罪恶谷的{link:ogres}食人魔{/link}就在前方不远处。]=],
		},
	},
})

Translate("zhCN", "deadwind-ravine", {
	title = "逆风谷",
	sections = {
		{
			title = "概述",
			text = [=[逆风谷是一道宽阔的山口，道路经由它从{link:duskwood}暮色森林{/link}攀入{link:deadwind-pass}逆风小径{/link}。在这里，幽暗的森林终于让位于灰色的岩石和枯死的树木。为小径命名的那股风在谷中刮得最猛，被称为天空之影的巨大食腐鸟乘风盘旋在头顶，留意着任何倒下的东西。对于从{link:darkshire}夜色镇{/link}来的人而言，这道{link:stranglethorn-vale}山谷{/link}让他们第一次看到一片比他们自己的土地更加荒凉的地方。]=],
		},
	},
})

Translate("zhCN", "deadwind-ogres", {
	title = "逆风食人魔",
	aliases = { "逆风的食人魔" },
	sections = {
		{
			title = "概述",
			text = [=[逆风食人魔是在{link:deadwind-pass}逆风小径{/link}南部定居的{link:ogres}食人魔{/link}。他们住在{link:the-vice}罪恶谷{/link}悬崖中挖出的土丘里，其中最大的是{link:grosh-gok-compound}格罗高克营地{/link}。没有任何编年史记载他们从何而来、何时到来，或者是什么吸引他们来到一片几乎没有任何生命的土地。]=],
		},
		{
			title = "他们的习性",
			text = [=[这个氏族有守卫营地和下方道路的蛮兵和重殴者。它也有照看土丘中篝火和大锅的术士和{link:ogres}食人魔{/link}法师。这个氏族中竟有术士，是一个不祥的迹象。黑暗法术是随{link:horde}部落{/link}一起来到{link:azeroth}艾泽拉斯{/link}的食人魔之中的，没有人知道这些食人魔是从谁那里学来的。]=],
		},
		{
			title = "当今",
			text = [=[{link:ogres}食人魔{/link}伏击任何偏离大路、走向{link:karazhan}卡拉赞{/link}的人。据人们所知，他们并不打扰那座塔，那座塔也不打扰他们。没有哪个王国派兵攻打过他们。{link:deadwind-pass}逆风小径{/link}离任何可能关心它的领主都太远了。]=],
		},
		{
			title = "未载",
			text = [=[{link:ogres}食人魔{/link}为何选择{link:the-vice}罪恶谷{/link}，他们想从如此死寂的土地上得到什么，都没有任何记载。他们首领的名字也无人知晓。]=],
		},
	},
})

